const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const region = ee.Geometry.Point(45.2044, 4.7358).buffer(10000); // Beledweyne, Somalia, 10km buffer
  const startDate2018 = '2018-05-01';
  const endDate2018 = '2018-05-31';
  const startDate2017 = '2017-05-01';
  const endDate2017 = '2017-05-31';

  // 2. Data Acquisition & Check
  const smapCollection = ee.ImageCollection('NASA_USDA/HSL/SMAP_soil_moisture').select('ssm');

  const col2018 = smapCollection.filterDate(startDate2018, endDate2018).filterBounds(region);
  const col2017 = smapCollection.filterDate(startDate2017, endDate2017).filterBounds(region);

  const size2018 = col2018.size().getInfo();
  const size2017 = col2017.size().getInfo();

  if (size2018 === 0 || size2017 === 0) {
    console.log(`Image count 2018: ${size2018}`);
    console.log(`Image count 2017: ${size2017}`);
    console.log('C1: Empty Collection');
    return;
  }

  // 3. Processing
  const mean2018 = col2018.mean().clip(region);
  const mean2017 = col2017.mean().clip(region);

  const scale = 1000; // SMAP resolution is coarse (~10km)

  const stats2018 = mean2018.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: region,
    scale: scale,
    maxPixels: 1e9
  });

  const stats2017 = mean2017.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: region,
    scale: scale,
    maxPixels: 1e9
  });

  const meanVal2018 = stats2018.get('ssm_mean').getInfo();
  const count2018 = stats2018.get('ssm_count').getInfo();
  const meanVal2017 = stats2017.get('ssm_mean').getInfo();
  const count2017 = stats2017.get('ssm_count').getInfo();

  // 4. Validation & Final Answer
  console.log(`May 2018 Mean Soil Moisture (mm): ${meanVal2018 ? meanVal2018.toFixed(2) : 'N/A'}`);
  console.log(`May 2018 Valid Pixel Count: ${count2018}`);
  console.log(`May 2017 Mean Soil Moisture (mm): ${meanVal2017 ? meanVal2017.toFixed(2) : 'N/A'}`);
  console.log(`May 2017 Valid Pixel Count: ${count2017}`);

  if (count2018 === 0 || count2017 === 0) {
    console.log('C2: No Valid Pixels');
    return;
  }

  if (meanVal2018 === null || meanVal2017 === null) {
    console.log('C3: Calculation Failure');
    return;
  }

  if (meanVal2018 > meanVal2017) {
    console.log('A');
  } else {
    console.log('B');
  }
}

